        for (unsigned long i = 0; i < count; ++i) {
            CQuaternion& rotation = from[i].Rotation;
            CQuaternion slerp;
            slerp.SetSlerp(rotation, to[i].Rotation, t);
            rotation = slerp;
        }
    }
    __int64 end;
    GF_GET_CYCLE_COUNT(end);
    g_BlendAnimationsCycles += end - start;
    g_BlendAnimationsKeyframes += count;
}

